(npx vite preview --port 4173 --strictPort > /tmp/e2e-check/preview.log 2>&1 &) ; sleep 4; cat /tmp/e2e-check/preview.log; cat > /tmp/e2e-check/check.mjs <<'EOF'
import { chromium } from 'playwright';

const URL = 'http://localhost:4173/';
const browser = await chromium.launch();
const results = [];
const check = (name, ok, extra = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);

// 1) English browser, fresh storage
{
  const ctx = await browser.newContext({ locale: 'en-US' });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(String(e)));
  await page.goto(URL);
  await page.waitForSelector('text=Welcome');
  check('en: default title', await page.getByText('Welcome', { exact: true }).isVisible());
  check('en: html lang=en', (await page.getByRole('document').getAttribute('lang')) === null
    ? (await page.evaluate(() => document.documentElement.lang)) === 'en'
    : false);
  check('en: switcher aria-label', (await page.getByRole('radiogroup', { name: 'Language' }).count()) === 1);
  await page.screenshot({ path: '/tmp/e2e-check/en.png', fullPage: true });

  await page.getByText('Русский', { exact: true }).click();
  await page.waitForSelector('text=Добро пожаловать');
  check('switch to ru: title', await page.getByText('Добро пожаловать', { exact: true }).isVisible());
  check('switch to ru: card', await page.getByText('Начало работы', { exact: true }).isVisible());
  check('switch to ru: html lang=ru', (await page.evaluate(() => document.documentElement.lang)) === 'ru');
  check('switch to ru: aria-label', (await page.getByRole('radiogroup', { name: 'Язык' }).count()) === 1);
  check('switch to ru: english gone', (await page.getByText('Welcome', { exact: true }).count()) === 0);
  const stored = await page.evaluate(() => localStorage.getItem('app-lang'));
  check('ru saved to localStorage', stored === 'ru', `stored=${stored}`);
  await page.screenshot({ path: '/tmp/e2e-check/ru.png', fullPage: true });

  await page.reload();
  await page.waitForSelector('text=Добро пожаловать');
  check('reload keeps ru', await page.getByText('Добро пожаловать', { exact: true }).isVisible());

  await page.getByText('English', { exact: true }).click();
  await page.waitForSelector('text=Welcome');
  check('switch back to en', await page.getByText('Welcome', { exact: true }).isVisible());
